<template>
  <div class="BuildingDetail">
    <header class="header">
      <h3>养殖信息分析</h3>
      <div class="backBtn" @click="$router.go(-1)">返回</div>
    </header>
    <div class="wrapper">
      <div class="container-fluid">
        <div class="row fill-h box">
          <div class="left fill-h">
            <div class="xpanel-wrapper xpanel-wrapper-1">
              <div class="xpanel no-bg">
                <div class="fill-h chart chartLayout" id="vr_container"></div>
              </div>
            </div>
          </div>
          <div class="right fill-h">
            <div class="xpanel-wrapper xpanel-wrapper-1-3">
              <div class="xpanel">
                <div class="fill-h right_Box">
                  <div class="left_top">
                    <div>养植物种：2类</div>
                    <div style="margin: 10px 0 0 0">养殖数量：18</div>

                    <div style="margin: 10px 0 10px 0">环境评估：优</div>
                  </div>
                  <div class="right_top" id="pieTest"></div>
                </div>
              </div>
            </div>
            <div class="xpanel-wrapper xpanel-wrapper-2-3">
              <div class="xpanel">
                <div class="fill-h" id="container"></div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import * as THREE from "three";
import * as echarts from "echarts";
// import { RGBELoader } from "three/examples/jsm/loaders/RGBELoader";
import { MTLLoader } from "three/examples/jsm/loaders/MTLLoader";
import { OBJLoader } from "three/examples/jsm/loaders/OBJLoader";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
export default {
  data() {
    return {
      scene: null,
      camera: null,
      mesh: null,
      renderer: null,
      controls: null,
      step: 0,
      name: this.$route.query.name,
      loading: true,
      sum: 0,
      testdata: [
        { value: 47, name: "20以下" },
        { value: 100, name: "20-30岁" },
        { value: 55, name: "30-40岁" },
        { value: 80, name: "40-50岁" },
        { value: 60, name: "60岁以上" },
      ],
      infoList: {
        name: "",
        height: "",
        floor: 0,
        square: "",
        malecount: 0,
        femalecount: 0,
      },
      ageStructure: {},
      agelst: [],
    };
  },
  mounted() {
    this.container = document.querySelector("#container");
    this.vrContainer = document.querySelector("#vr_container");
    this.init();
    this.initControls();
    this.initCharts();
    this.vrContainer.style.display = "block";
    this.initLight();
    this.initModelMed("yangzhichang").then(() => {
      this.loading = false;
      this.anmiation();
    });
    this.resize();
  },
  methods: {
    init() {
      // 1.创建场景
      this.scene = new THREE.Scene();
      // 2.创建摄像机
      this.camera = new THREE.PerspectiveCamera(
        70,
        this.container.clientWidth / this.container.clientHeight,
        10,
        10000
      );
      //    3.创建threejs渲染器
      this.renderer = new THREE.WebGLRenderer({ antialias: true });
      this.renderer.outputEncoding = THREE.sRGBEncoding;
      this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
      // 4.设置渲染器场景的大小
      this.renderer.setClearColor(new THREE.Color("#0f1c30"));
      this.renderer.setSize(
        this.container.clientWidth,
        this.container.clientHeight
      );

      // 设置渲染物体阴影
      this.renderer.shadowMap.enabled = true;
      // 把渲染器添加到页面当中去
      this.container.appendChild(this.renderer.domElement);
      //  创建控制器
      this.camera.position.set(200, 300, 1000);
      this.camera.lookAt(this.scene.position);
    },
    initControls() {
      this.controls = new OrbitControls(this.camera, this.renderer.domElement);
      // 使动画循环使用时阻尼或自转 意思是否有惯性
      this.controls.enableDamping = true;
      //是否可以缩放
      this.controls.enableZoom = true;
      //是否自动旋转
      this.controls.autoRotate = false;
      //设置相机距离原点的最近距离
      this.controls.minDistance = 50;
      //设置相机距离原点的最远距离
      this.controls.maxDistance = 5000;
      //是否开启右键拖拽
      this.controls.enablePan = true;
      // 最大角度
      this.controls.maxPolarAngle = Math.PI / 2.2;
    },
    initLight() {
      const PointLight = new THREE.PointLight(0xffffff, 0.6);
      this.scene.add(PointLight);
      const ambient = new THREE.AmbientLight(0xffffff);
      this.scene.add(ambient);
      this.camera.add(PointLight);
    },
    // 初始化图表
    initCharts() {
      for (const ele of document.querySelectorAll(".chart")) {
        // ele.style.backgroundColor = "rgba(25,25,25,0.5)";
        ele.style.display = ele.style.display === "block" ? "block" : "block";
      }
      const div1 = document.querySelector("#vr_container");
      const pageChart1 = echarts.init(div1);
      const option1 = {
        legend: {
          textStyle: {
            color: "#eee",
          },
        },
        tooltip: {},
        dataset: {
          source: [
            ["product", "2015", "2016", "2017"],
            ["Matcha Latte", 43.3, 85.8, 93.7],
            ["Tea", 83.1, 73.4, 55.1],
            ["Cheese Cocoa", 86.4, 65.2, 82.5],
            ["Walnut Brownie", 72.4, 53.9, 39.1],
          ],
        },
        xAxis: {
          type: "category",
          textStyle: {
            color: "#eee",
          },
        },
        yAxis: {},
        // Declare several bar series, each will be mapped
        // to a column of dataset.source by default.
        series: [{ type: "bar" }, { type: "bar" }, { type: "bar" }],
      };
      pageChart1.setOption(option1);
      this.container.appendChild(div1);
    },
    // 初始化模型
    initModelMed(url) {
      return new Promise((resolve, reject) => {
        new MTLLoader()
          .setPath("/static/obj/farm/")
          .load(`${url}.mtl`, (materials) => {
            materials.preload();
            new OBJLoader()
              .setMaterials(materials)
              .setPath("/static/obj/farm/")
              .load(`${url}.obj`, (obj) => {
                if (obj) {
                  console.log(obj);
                  this.loading = false;
                  this.farmModel = obj;
                  obj.scale.set(0.1, 0.1, 0.1);
                  this.scene.add(obj);
                  resolve(obj);
                } else {
                  reject("error");
                }
              });
          });
      });
    },

    // 动画
    anmiation() {
      requestAnimationFrame(this.anmiation);
      this.controls.update();
      this.renderer.render(this.scene, this.camera);
    },
    // 动态设置屏幕宽高占比
    resize() {
      window.addEventListener("resize", () => {
        // 初始化摄像机
        this.camera.aspect =
          this.container.clientWidth / this.container.clientHeight;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(
          this.container.clientWidth,
          this.container.clientHeight
        );
      });
    },
  },
};
</script>

<style src="../assets/css/page/app.css"></style>
